type Settings = { bias: number, visit: number -> unit }
let make = (settings: Settings) => let bias = settings.bias in let visit = settings.visit in value => switch value {
| Err(e) => let used = visit(e) in loop (i = 0, acc = e - bias) { i >= 20 ? acc : recur(i + 1, (acc * 17 + 23) % 65536) }
| Ok(n) => let used = visit(n) in loop (i = 0, acc = n + bias) { i >= 20 ? acc : recur(i + 1, (acc * 17 + 23) % 65536) }
}

type Settings = { bias: number, visit: number -> unit }
let make = (settings: Settings) => let bias = settings.bias in let visit = settings.visit in value => switch value {
| None => let used = visit(0) in loop (i = 0, acc = bias) { i >= 20 ? acc : recur(i + 1, (acc * 17 + 23) % 65536) }
| Some(n) => let used = visit(n) in loop (i = 0, acc = n + bias) { i >= 20 ? acc : recur(i + 1, (acc * 17 + 23) % 65536) }
}

type Shape = Dot | Box(value: number) | Pair(number, number)
type Settings = { bias: number, visit: number -> unit }
let make = (settings: Settings) => let bias = settings.bias in let visit = settings.visit in (value: Shape) => switch value {
  | Dot => bias
  | Box(n) => n + bias
  | Pair(a, b) => a + b
}

type Shape = Dot | Box(value: number) | Pair(number, number)
type Settings = { bias: number, visit: number -> unit }
let make = (settings: Settings) => let bias = settings.bias in let visit = settings.visit in (value: Shape) => switch value {
  | Dot => let used = visit(0) in bias
  | Box(n) => let used = visit(n) in n + bias
  | Pair(a, b) => let used = visit(a) in a + b
}

